css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:80px}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased;overflow-x:clip}
h1,h2,h3,h4,h5{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.12;letter-spacing:-.02em}
p{margin:0}a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px;position:relative;z-index:1}
section{padding:96px 0;position:relative}
.dk{background:var(--k);color:#fff}.lt{background:var(--w);color:var(--ink)}
.dk p{color:var(--dmute)}.lt p{color:var(--mute)}
.gb::before{content:"";position:absolute;inset:0;background-image:linear-gradient(var(--gl) 1px,transparent 1px),linear-gradient(90deg,var(--gl) 1px,transparent 1px);background-size:56px 56px;-webkit-mask-image:linear-gradient(#000,transparent 85%);mask-image:linear-gradient(#000,transparent 85%);pointer-events:none}
.dk.gb{--gl:#ffffff0a}.lt.gb{--gl:#0000000a}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}
.b-l{background:var(--l);color:var(--k)}.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}.b-d{background:var(--k);color:#fff}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
.eb{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;margin-bottom:20px}
.eb::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l);box-shadow:0 0 0 3px #080808}
.dk .eb{color:var(--l)}.lt .eb{color:var(--ink)}.lt .eb::before{box-shadow:none;background:var(--k)}
.sh{max-width:760px;margin-bottom:48px}
.sh h2{font-size:clamp(28px,4vw,46px);letter-spacing:-.03em}.sh p{margin-top:16px;font-size:17px;max-width:620px}
.cpl{display:inline-block;font:600 12px Inter;background:var(--l);color:var(--k);padding:5px 13px;border-radius:99px}
.fine{margin-top:22px;font-size:14px}
nav{position:sticky;top:0;z-index:30;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-size:14.5px;color:#d0d0d4}
nav ul a:hover,nav ul a.on{color:var(--l)}nav .btn{padding:10px 18px;font-size:14px}
/* reveal */
.js .rv{opacity:0;transform:translateY(26px);transition:opacity .7s ease,transform .7s ease;transition-delay:var(--d,0s)}
.js .rv.in{opacity:1;transform:none}
/* hero */
.hero{padding:80px 0 72px;background:radial-gradient(circle at 85% 0,#C7FF3F14,transparent 45%),var(--k)}
.hero h1{font-size:clamp(34px,5.2vw,68px);line-height:1.03;letter-spacing:-.038em;max-width:960px}
.hero .sub{margin:22px 0 32px;font-size:clamp(17px,2vw,19px);max-width:600px;color:#d6d6da}
.hc{position:relative;margin-top:64px;padding-bottom:50px}
.hc .cpl{position:absolute;left:18px;top:-14px;z-index:3}
.hc .br{width:90%}
.hc .ph{position:absolute;right:0;bottom:0;--pw:196px;transform:rotate(2deg)}
.sum{display:grid;grid-template-columns:repeat(4,1fr);margin-top:56px;border-top:1px solid var(--dline)}
.sum div{padding:22px 24px 0 0}.sum small{display:block;font:600 12px Inter;letter-spacing:.08em;color:var(--dmute);margin-bottom:6px}.sum b{font:600 16px Sora;color:#fff;line-height:1.35}
/* frame + primitives */
.br{background:var(--k2);border:1px solid var(--dline);border-radius:16px;box-shadow:0 24px 50px #000a;overflow:hidden;position:relative}
.top{display:flex;align-items:center;gap:6px;padding:11px 14px;border-bottom:1px solid var(--dline)}
.top b{width:9px;height:9px;border-radius:50%;background:#333}.top .url{margin-left:12px;font-size:12px;color:var(--dmute);background:#1a1a1e;border-radius:99px;padding:4px 14px}
.pill{display:inline-block;padding:6px 13px;border-radius:99px;background:var(--l);color:var(--k);font:600 11px Inter;white-space:nowrap}
.tag{font-size:10.5px;padding:3px 9px;border-radius:99px;background:#222226;color:var(--dmute);white-space:nowrap}
.fd{padding:9px 10px;border-radius:9px;background:#17171a;border:1px solid var(--dline);font-size:11px;color:var(--dmute)}.fd b{display:block;font:600 15px Sora;color:#fff}
.rw{display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:10px;background:#17171a;border:1px solid var(--dline);font-size:11.5px;color:#ddd}
.rw.on{border-color:var(--l)}.rw .av{width:22px;height:22px;border-radius:50%;background:#2a2a2e;flex:none}.rw .ln{flex:1}.rw>.pill,.rw>.tag{margin-left:auto}
.ln{height:7px;border-radius:4px;background:#2a2a2e}.ln.w{height:11px;background:#e9e9ea;width:50%}.ln.s{width:60%}
.dsh{display:grid;grid-template-columns:54px 1fr}
.sd{border-right:1px solid var(--dline);padding:16px 0;display:flex;flex-direction:column;align-items:center;gap:14px}.sd i{width:22px;height:22px;border-radius:7px;background:#2a2a2e}.sd i:first-child{background:var(--l)}
.mn{padding:18px;display:flex;flex-direction:column;gap:10px}.mn h5{font-size:14px;color:#fff}
.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.g2{display:grid;grid-template-columns:1.4fr 1fr;gap:10px}
.tb{display:flex;gap:6px;flex-wrap:wrap}.tb i{font-style:normal;font-size:11px;padding:4px 11px;border-radius:99px;background:#1b1b1f;color:var(--dmute)}.tb i.on{background:var(--l);color:var(--k);font-weight:600}
.bars{display:flex;align-items:flex-end;gap:7px;height:76px;padding-top:6px}.bars i{flex:1;background:#2a2a2e;border-radius:4px 4px 0 0}.bars i:last-child{background:var(--l)}
.card{background:#17171a;border:1px solid var(--dline);border-radius:12px;padding:12px;font-size:11px;color:var(--dmute)}.card h5{font-size:12px;color:#fff;margin-bottom:8px}
/* phones */
.ph{--pw:210px;width:var(--pw);aspect-ratio:9/18.5;background:#1a1a1e;border:2px solid #34343a;border-radius:34px;padding:8px;box-shadow:0 24px 50px #000a;position:relative;flex:none}
.sc{height:100%;background:var(--w);border-radius:26px;overflow:hidden;color:var(--ink);padding:2.6em 1.1em 1em;font-size:calc(var(--pw)/20);display:flex;flex-direction:column;gap:.7em;position:relative;line-height:1.35}
.sc::before{content:"";position:absolute;top:.8em;left:50%;transform:translateX(-50%);width:5em;height:1.3em;border-radius:1em;background:#111}
.sc h5{font-size:1.35em}.sc p{color:var(--mute)}
.chips{display:flex;gap:.5em}.chips i{font-style:normal;flex:1;text-align:center;padding:.5em 0;border-radius:.8em;background:var(--g);font-weight:500}.chips i.on{background:var(--k);color:var(--l)}
.it{display:flex;justify-content:space-between;align-items:center;gap:.5em;padding:.9em;border:1px solid var(--line);border-radius:1em;background:#fff}
.it span{color:var(--mute);font-size:.9em}.it.on{border-color:var(--k);box-shadow:0 0 0 .2em #C7FF3F88}
.bt{margin-top:auto;background:var(--k);color:#fff;text-align:center;padding:.95em;border-radius:99px;font-weight:600}
.cd{background:var(--k);color:#fff;border-radius:1.1em;padding:1em}.cd span{display:block;color:#aaa;font-size:.9em}.cd b{font:600 1.15em Sora}
.ok{width:4em;height:4em;border-radius:50%;background:var(--l);margin:1.2em auto .4em;display:grid;place-items:center;font:700 1.8em Inter;color:var(--k)}
.big-bt{margin:auto;width:9em;height:9em;border-radius:50%;background:var(--l);color:var(--k);display:grid;place-items:center;font:700 1.2em Sora;box-shadow:0 0 0 .6em #C7FF3F44}
.tbar{margin-top:auto;display:flex;justify-content:space-around;padding-top:.7em;border-top:1px solid var(--line)}.tbar i{width:1.3em;height:1.3em;border-radius:50%;background:#d6d7d3}.tbar i:first-child{background:var(--k)}
/* challenge */
.cc{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.ch{background:#fff;border:1px solid var(--line);border-radius:24px;padding:32px;min-height:260px;display:flex;flex-direction:column}
.ch .n{font:700 44px Sora;letter-spacing:-.04em;color:#d7d9d3;margin-bottom:auto;padding-bottom:36px}
.ch h3{font-size:21px;margin-bottom:10px}.ch p{font-size:15.5px}
/* ecosystem */
.eco{display:grid;grid-template-columns:repeat(6,1fr);gap:0;align-items:stretch}
.nd{position:relative;margin-right:30px;background:var(--k2);border:1px solid var(--dline);border-radius:16px;padding:18px 16px;display:flex;flex-direction:column;gap:10px}
.nd:last-child{margin-right:0}
.nd .t{font:600 11px Inter;color:var(--l);letter-spacing:.04em}
.nd h4{font-size:15px;color:#fff;line-height:1.25}.nd .ln{margin-top:auto}
.nd::after{content:"→";position:absolute;left:100%;top:50%;width:30px;transform:translateY(-50%);text-align:center;color:var(--l);font:600 18px Sora}
.nd:last-child::after{display:none}.nd.hi{border-color:var(--l)}
/* features */
.ft .wrap{display:grid;grid-template-columns:1fr 1.4fr;gap:56px;align-items:center}
.ft.rev .tx{order:2}
.ft .no{font:600 13px Sora;margin-bottom:14px}.dk .no{color:var(--l)}.lt .no{color:var(--mute)}
.ft h3{font-size:clamp(26px,3vw,38px);letter-spacing:-.03em;margin-bottom:14px}.ft .tx p{font-size:16.5px;max-width:440px;margin-bottom:20px}
.stg{border-radius:28px;padding:34px;position:relative;overflow:hidden;min-height:440px;display:flex;align-items:center;justify-content:center}
.lt .stg{background:var(--k)}.dk .stg{background:radial-gradient(circle at 70% 20%,#1c1c20,#0e0e10 70%);border:1px solid var(--dline)}
.stg .br{width:100%}.stg .cpl{position:absolute;left:18px;top:16px;z-index:3}
.kb{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.kb>div{display:flex;flex-direction:column;gap:8px}.kb h6{margin:0;font:600 11px Inter;color:var(--dmute)}
.wk{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;font-size:11px}.wk>div{display:flex;flex-direction:column;gap:8px}.wk h6{margin:0;font:600 11px Inter;color:var(--dmute);text-align:center}
.ev{border-radius:9px;background:#17171a;border:1px solid var(--dline);padding:8px;color:#ddd;font-size:11px;line-height:1.3}.ev small{display:block;color:var(--dmute);font-size:10px}.ev.on{border-color:var(--l)}.ev.t{height:64px}.ev.m{height:46px}
.ov{position:absolute;right:12px;bottom:-56px;--pw:170px;transform:rotate(3deg)}
.ft .cars{display:flex;gap:14px;align-items:center}.cars .ph{--pw:180px}.cars .ph:nth-child(2){--pw:200px;margin-top:-28px}
.fl{display:flex;flex-direction:column;width:100%;max-width:420px;gap:0}.fl .rw{padding:14px;font-size:13px;border-radius:12px;flex-direction:column;align-items:flex-start;gap:3px}.fl .rw b{font:600 14px Sora;color:#fff}.fl .rw span{color:var(--dmute);font-size:12px}
.fl s{align-self:center;width:2px;height:22px;background:var(--l);opacity:.6;text-decoration:none}
/* roles */
.rl{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.r{border:1px solid var(--dline);border-radius:24px;padding:32px;background:var(--k2)}
.r h3{font-size:22px;color:#fff;margin-bottom:22px}.r ul{list-style:none;margin:0;padding:0}.r li{padding:11px 0;border-top:1px solid var(--dline);color:#d8d8dc;font-size:15.5px;display:flex;gap:12px;align-items:center}.r li::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--l);flex:none}
/* design system */
.ds{background:var(--k);border-radius:28px;padding:28px;display:grid;grid-template-columns:repeat(3,1fr);gap:16px;color:#fff}
.dt{border:1px solid var(--dline);border-radius:18px;padding:20px;background:var(--k2)}
.dt>small{display:block;font:600 11px Inter;letter-spacing:.08em;color:var(--dmute);margin-bottom:16px}
.aa{font:700 56px/1 Sora;letter-spacing:-.04em}.dt .bd{font-size:13px;color:var(--dmute);margin-top:10px}
.sw{display:flex;gap:8px}.sw i{flex:1;aspect-ratio:1;border-radius:10px;border:1px solid #333}.sw+.sw{margin-top:8px}
.hx{display:flex;gap:8px;font-size:10px;color:var(--dmute);margin-top:8px}.hx span{flex:1}
.bs{display:flex;flex-wrap:wrap;gap:10px}.bs .btn{padding:10px 18px;font-size:13.5px}
.in{display:block;padding:11px 13px;border-radius:10px;background:#17171a;border:1px solid var(--dline);font-size:13px;color:var(--dmute);margin-bottom:10px}.in.f{border-color:var(--l);color:#fff}
.tt{width:100%;font-size:12.5px;border-collapse:collapse}.tt th{text-align:left;color:var(--dmute);font-weight:500;padding:6px 0;border-bottom:1px solid var(--dline)}.tt td{padding:9px 0;border-bottom:1px solid var(--dline);color:#ddd}
.pc{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:40px}.pc h4{font-size:18px;margin-bottom:8px}.pc p{font-size:15px}
/* automation steps */
.as{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.s{background:var(--k2);border:1px solid var(--dline);border-radius:20px;padding:28px;position:relative}
.s .n{font:700 34px Sora;color:var(--l);letter-spacing:-.03em;margin-bottom:14px}.s p{color:#e4e4e7;font-size:16px}
.s::after{content:"→";position:absolute;right:-16px;top:50%;transform:translateY(-50%);width:14px;color:var(--l);font:600 16px Sora;z-index:2}
.s:nth-child(3n)::after,.s:last-child::after{display:none}
/* strip */
.sp{display:flex;align-items:center;gap:24px}
.sp>div:not(.ar){flex:1}.sp h3{font-size:clamp(30px,4vw,48px);letter-spacing:-.035em;margin-bottom:10px}.sp p{font-size:15.5px;max-width:300px}
.ar{flex:none;width:88px;height:2px;background:var(--line);position:relative}
.ar::after{content:"";position:absolute;top:-5px;left:0;width:12px;height:12px;border-radius:50%;background:var(--l);border:2px solid var(--k);animation:go 2.6s ease-in-out infinite}
@keyframes go{0%{left:0;opacity:0}15%,85%{opacity:1}100%{left:calc(100% - 12px);opacity:0}}
@keyframes godn{0%{top:0;opacity:0}15%,85%{opacity:1}100%{top:calc(100% - 12px);opacity:0}}
/* tech */
.tp{display:flex;flex-wrap:wrap;gap:12px}.tp span{padding:11px 20px;border:1px solid var(--dline);border-radius:99px;font-size:15px;color:#e4e4e7;background:var(--k2)}
/* approach */
.ap{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.a{background:#fff;border:1px solid var(--line);border-radius:20px;padding:28px}
.a b{display:block;font:600 13px Sora;letter-spacing:.06em;margin-bottom:16px;padding-bottom:12px;border-bottom:2px solid var(--l)}.a p{font-size:15.5px}
/* next */
.nx{display:grid;grid-template-columns:1fr 1.2fr;gap:56px;align-items:center}
.nx h2{font-size:clamp(32px,4.4vw,56px);letter-spacing:-.035em;margin:6px 0 14px}.nx .m{font:600 14px Inter;color:var(--l);margin-bottom:26px}
.hs{background:var(--w);color:var(--ink)}
.sn{display:flex;justify-content:space-between;align-items:center;padding:12px 20px;font-size:12px;border-bottom:1px solid var(--line)}.sn b{font:700 14px Sora}.sn em{font-style:normal;background:var(--k);color:#fff;padding:6px 13px;border-radius:99px;font-weight:600}
.hh{margin:16px 20px;border-radius:14px;background:linear-gradient(160deg,#1b1b1f,#0c0c0e);color:#fff;padding:26px 24px 44px;position:relative}
.hh h3{font-size:24px;max-width:300px;letter-spacing:-.03em}.hh p{font-size:12px;color:#bbb;margin-top:8px}
.bk{position:absolute;left:16px;right:16px;bottom:-22px;background:#fff;color:var(--ink);border-radius:12px;padding:11px 14px;display:grid;grid-template-columns:repeat(3,1fr) auto;gap:10px;font-size:11px;box-shadow:0 12px 26px #0004;align-items:center}
.bk span{color:var(--mute);display:block;font-size:10px}.bk b{font-weight:600}
.rms{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:34px 20px 20px}.rms div{border:1px solid var(--line);border-radius:10px;padding:9px;font-size:11px;font-weight:600;background:#fff}.rms i{display:block;height:40px;border-radius:6px;background:var(--g);margin-bottom:6px}
/* cta */
.cta{background:var(--l);color:var(--k)}
.cta h2{font-size:clamp(34px,6vw,68px);letter-spacing:-.035em;max-width:820px}
.cta p{margin:18px 0 32px;font-size:18px;max-width:560px;color:#2a3300}.cta .fine{color:#3a4400;margin-top:26px}
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.fg{display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:40px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}footer h4{font-size:14px;margin-bottom:14px}
footer ul{list-style:none;margin:0;padding:0}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet */
@media(max-width:1020px){
.sum{grid-template-columns:1fr 1fr}.hc .br{width:100%}.hc .ph{display:none}.hc{padding-bottom:0}
.cc,.rl,.pc{grid-template-columns:1fr}.eco{grid-template-columns:1fr;gap:0}
.nd{margin:0 0 30px}.nd::after{content:"↓";left:50%;top:100%;transform:translateX(-50%);height:30px;width:auto;line-height:30px}
.ft .wrap,.nx{grid-template-columns:1fr;gap:36px}.ft.rev .tx{order:0}.ft .tx p{max-width:none}
.ds{grid-template-columns:1fr 1fr}.as{grid-template-columns:1fr 1fr}.s:nth-child(3n)::after{display:block}.s:nth-child(2n)::after,.s:last-child::after{display:none}
.ap{grid-template-columns:1fr 1fr}.fg{grid-template-columns:1fr 1fr}}
@media(max-width:860px){nav ul{display:none}
.sp{flex-direction:column;align-items:flex-start}.sp p{max-width:none}.ar{width:2px;height:48px}.ar::after{top:0;left:-5px;animation-name:godn}}
/* mobile */
@media(max-width:600px){
section{padding:68px 0}.wrap{padding:0 20px}.hero{padding:56px 0 52px}.hc{margin-top:44px}
.sum{grid-template-columns:1fr}.sum div{padding:16px 0 0}
.stg{padding:18px;min-height:0}.stg .br{margin-top:22px}.dsh{grid-template-columns:1fr}.sd{display:none}.g3{grid-template-columns:1fr 1fr}.g3>:last-child{display:none}.g2{grid-template-columns:1fr}
.kb{grid-template-columns:1fr 1fr}.wk{grid-template-columns:repeat(3,1fr)}.wk>div:nth-child(n+4){display:none}.ov{display:none}
.ft .cars{gap:8px}.cars .ph,.cars .ph:nth-child(2){--pw:104px;border-radius:20px;padding:5px;margin:0}.cars .ph:nth-child(2){--pw:114px}.cars .sc{padding:2.6em .8em .8em;border-radius:16px}
.ds,.as,.ap,.fg{grid-template-columns:1fr}.s::after{display:none!important}.ds{padding:16px}
.bk{grid-template-columns:1fr 1fr}.bk .pill{grid-column:span 2;text-align:center}.hh{padding-bottom:84px}.rms{padding-top:80px}
.ctas .btn{width:100%;justify-content:center}.ch{min-height:0}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}.js .rv{opacity:1;transform:none}}

js:
(function(){
  var els=document.querySelectorAll('.rv');
  if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    els.forEach(function(e){e.classList.add('in')});return;
  }
  var io=new IntersectionObserver(function(es){
    es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});
  },{threshold:.12,rootMargin:'0px 0px -6% 0px'});
  els.forEach(function(e){io.observe(e)});
})();
